import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;
    private long[] fact;
    private long[] invFact;
    private int maxN;

    public int numOfWays(int[] nums) {
        int n = nums.length;
        maxN = n;
        initFactorials(n);
        List<Integer> arr = new ArrayList<>();
        for (int v : nums) arr.add(v);
        long totalWays = ways(arr);
        // subtract the original ordering
        long ans = (totalWays - 1 + MOD) % MOD;
        return (int) ans;
    }

    private void initFactorials(int n) {
        fact = new long[n + 1];
        invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;
    }

    private long nCk(int n, int k) {
        if (k < 0 || k > n) return 0;
        return (((fact[n] * invFact[k]) % MOD) * invFact[n - k]) % MOD;
    }

    private long ways(List<Integer> arr) {
        int m = arr.size();
        if (m <= 2) return 1;
        int root = arr.get(0);
        List<Integer> left = new ArrayList<>();
        List<Integer> right = new ArrayList<>();
        for (int i = 1; i < m; i++) {
            int v = arr.get(i);
            if (v < root) left.add(v);
            else right.add(v);
        }
        long leftWays = ways(left);
        long rightWays = ways(right);
        long choose = nCk(left.size() + right.size(), left.size());
        long res = choose;
        res = (res * leftWays) % MOD;
        res = (res * rightWays) % MOD;
        return res;
    }

    private long modPow(long a, long e) {
        long res = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }
}

